import{_ as n,C as s,o as r,c as i,a2 as e,E as o}from"./chunks/framework.CGSzHL4z.js";const b=JSON.parse('{"title":"Action blocks, events and audio","description":"","frontmatter":{},"headers":[],"relativePath":"features/blocks-and-audio.md","filePath":"features/blocks-and-audio.md","lastUpdated":1792713747000}'),d={name:"features/blocks-and-audio.md"};function l(c,t,h,p,u,g){const a=s("Screenshot");return r(),i("div",null,[t[0]||(t[0]=e('<h1 id="action-blocks-events-and-audio" tabindex="-1">Action blocks, events and audio <a class="header-anchor" href="#action-blocks-events-and-audio" aria-label="Permalink to &quot;Action blocks, events and audio&quot;">​</a></h1><p>Some things in a scene happen at a moment rather than change over time: a sound plays, an emitter bursts, a trail turns on, your game code hears &quot;Hit&quot;. AcesMotion puts these on the Timeline as calls, action blocks and audio clips, so you time them against the animation and the runtime fires them in games.</p><h2 id="calls-sounds-and-emitters" tabindex="-1">Calls: sounds and emitters <a class="header-anchor" href="#calls-sounds-and-emitters" aria-label="Permalink to &quot;Calls: sounds and emitters&quot;">​</a></h2><p>An object&#39;s methods can be keyed like properties. In the <a href="./inspector#calls-and-attributes">Inspector&#39;s</a> Calls section, click the diamond beside a sound&#39;s <code>Play()</code> or <code>Stop()</code>, an emitter&#39;s <code>Emit()</code> or <code>Clear()</code>, a Trail&#39;s <code>Clear()</code>, or a VideoFrame&#39;s <code>Play()</code> or <code>Pause()</code>. Calls run while the Timeline plays (not while you scrub) and in games.</p><h3 id="sound-bars" tabindex="-1">Sound bars <a class="header-anchor" href="#sound-bars" aria-label="Permalink to &quot;Sound bars&quot;">​</a></h3><p>Each <code>Play()</code> key draws as a bar from its flag to where the sound ends, with the sound&#39;s name, a waveform and a speed chip when the speed isn&#39;t 1. A later <code>Stop()</code> key cuts the bar.</p>',6)),o(a,{name:"fig-sound-rows",caption:"Sound rows expanded with waveforms, including a waveform still loading, an unavailable one and a narrow bar."}),t[1]||(t[1]=e('<table tabindex="0"><thead><tr><th>To</th><th>Do</th></tr></thead><tbody><tr><td>Trim the start (the audio stays put)</td><td>Drag the left edge</td></tr><tr><td>Trim the end</td><td>Drag the right edge; double click it to clear the trim</td></tr><tr><td>Change the speed (0.25x to 4x, pitch follows)</td><td><code>Ctrl</code>+drag the right edge</td></tr><tr><td>Fade in or out</td><td>Drag the fade grips that appear on hover</td></tr><tr><td>Move a looped sound&#39;s loop</td><td>Drag the loop handles</td></tr><tr><td>Trim to the playhead</td><td>Right click &gt; <strong>Start at</strong> or <strong>End at</strong></td></tr></tbody></table><p>Right click a fade for its shape: Linear, Equal power, Slow start or S-curve. Dragging an edge, a fade or the playhead over a bar plays short audio snippets. Keys, the playhead and markers snap to a sound&#39;s loud hits (&quot;snap: Roar peak&quot;). <strong>View &gt; Sound rows</strong> switches between <strong>Compact</strong> and <strong>Expanded</strong> rows.</p><h3 id="effect-bars" tabindex="-1">Effect bars <a class="header-anchor" href="#effect-bars" aria-label="Permalink to &quot;Effect bars&quot;">​</a></h3><p>Each <code>Emit()</code> key shows a lime burst bar, solid up to the particles&#39; minimum life and fading out to their maximum, with &quot;×20&quot; on it. Drag its end grip or its knob to set that burst&#39;s life, with the viewport updating as you drag. An emitter that&#39;s Enabled with a Rate above 0 shows a thinner stream band; its grips set the emitter&#39;s Lifetime.</p><p>Overlapping sound and burst bars stack in up to 4 sub-lanes. Drag a bar up or down to choose its lane; right click &gt; <strong>Reset lane</strong> lets it stack on its own again.</p><h2 id="action-tracks-and-blocks" tabindex="-1">Action tracks and blocks <a class="header-anchor" href="#action-tracks-and-blocks" aria-label="Permalink to &quot;Action tracks and blocks&quot;">​</a></h2><p>An actor can have any number of action tracks: right click the actor row &gt; <strong>Add action track</strong>. Right click an empty spot of the lane &gt; <strong>Add block</strong> to add an <strong>Event</strong> or one of your custom actions.</p>',7)),o(a,{name:"fig-action-track",caption:"An Actions row with Toggle Trail blocks that have a duration and an instant 'Event: Hit' block."}),t[2]||(t[2]=e('<p>A block is either an <strong>instant</strong>, a chip centred on its frame, or a bar with a <strong>duration</strong>. Blocks draw in the actor&#39;s colour.</p><table tabindex="0"><thead><tr><th>To</th><th>Do</th></tr></thead><tbody><tr><td>Select</td><td>Click; <code>Shift</code> adds, <code>Ctrl</code> toggles, drag on empty lane space to box-select</td></tr><tr><td>Move</td><td>Drag the body; <code>Ctrl</code>+drag copies; <code>Alt</code> flips snapping</td></tr><tr><td>Trim</td><td>Drag the grip at either end of a bar</td></tr><tr><td>Duplicate, delete</td><td><code>Shift+D</code>, <code>Del</code></td></tr><tr><td>Trim to the playhead</td><td>Right click &gt; <strong>Start at</strong> or <strong>End at</strong></td></tr><tr><td>Rename the track</td><td><code>F2</code> with the track&#39;s header selected</td></tr></tbody></table>',2)),o(a,{name:"fig-block-states",caption:"Action block states: a duration block at rest, hovered and selected with its grips, an instant Event chip, a block whose module failed (dashed), a muted block, one too short for its label, labels cut short, compact rows, and the eight actor tints."}),t[3]||(t[3]=e('<p>A block whose module is missing or failed to load draws dashed red with a warning icon and says why in its tooltip. It keeps its place and data, and still moves, trims and deletes. A muted track draws at 50% and its blocks don&#39;t run.</p><p>In Studio, duration blocks run as the playhead enters them and clean up as it leaves, playing or scrubbing. Instants fire only while playing, unless <strong>Settings &gt; Actions &gt; Fire instant actions while scrubbing</strong> is on.</p><h3 id="event-blocks" tabindex="-1">Event blocks <a class="header-anchor" href="#event-blocks" aria-label="Permalink to &quot;Event blocks&quot;">​</a></h3><p>An <strong>Event</strong> block is an instant your game code listens for. It reads &quot;Event: Hit&quot; on the Timeline. In the Inspector it has a <strong>Name</strong> and a <strong>Payload</strong>: a table of named values, each a Number, String, Boolean, Vector3 or Color3. In a game, <code>AcesMotion.OnEvent(&quot;Hit&quot;, callback)</code> calls your function with the track and the payload whenever an Event block named Hit fires.</p><h3 id="custom-actions" tabindex="-1">Custom actions <a class="header-anchor" href="#custom-actions" aria-label="Permalink to &quot;Custom actions&quot;">​</a></h3><p>Custom actions are ModuleScripts tagged <code>AcesMotionAction</code>, kept anywhere the server and clients can require them, such as ReplicatedStorage. The module&#39;s <code>Params</code> become fields in the block&#39;s Inspector panel. See <a href="/AcesMotion-docs/extend/custom-actions">Custom actions</a> for a walkthrough and <a href="/AcesMotion-docs/api/actions">the API reference</a> for the module contract.</p><p>The block panel shows <strong>Timing</strong> (Start, Length and Ends at, in the ruler&#39;s units), then one row per parameter. Right click a parameter row for <strong>Reset to default</strong>. With several blocks of one action selected, edits apply to all of them.</p><h2 id="audio-lanes" tabindex="-1">Audio lanes <a class="header-anchor" href="#audio-lanes" aria-label="Permalink to &quot;Audio lanes&quot;">​</a></h2><p>Audio lanes hold the scene&#39;s own sounds: music, voice-over, ambience, anything that belongs to no actor. They sit under an <strong>Audio</strong> row after the last actor. Each lane has its own Mute, Lock and volume.</p>',9)),o(a,{name:"fig-audio-lanes",caption:"The Audio group with Music, Voice and Ambience lanes: clips with waveforms, fades and loop marks, and a 3D clip."}),t[4]||(t[4]=e('<p>Add a lane with <strong>+ Add &gt; Add audio lane</strong>. <strong>Add selected sound</strong> puts the Sound or AudioPlayer selected in the Explorer on a lane at the playhead. It asks each time whether to <strong>Use as template</strong> (play that Sound itself, with its own effects) or <strong>Copy its id</strong> (take its id, volume, speed and loop, so the Sound isn&#39;t needed afterwards).</p><p>Clips work exactly like sound bars: trims, fades, loops, <code>Ctrl</code> speed stretch, sub-lanes, audio scrubbing and peak snapping. They select like keys, so one box can take keys and clips together and move them as one.</p><h3 id="the-clip-panel" tabindex="-1">The clip panel <a class="header-anchor" href="#the-clip-panel" aria-label="Permalink to &quot;The clip panel&quot;">​</a></h3>',3)),o(a,{name:"fig-audio-clip",caption:"The Inspector's audio clip panel for a clip named Theme on the Music lane: its asset id, and Play as 2D."}),t[5]||(t[5]=e('<p>Select a clip for its panel: <strong>Timing</strong>, <strong>Sound</strong> (an asset id or a template), <strong>Playback</strong> (Volume as a share of the lane&#39;s, Speed, Start at and Stop at, Loop, fades) and <strong>Position</strong> (play as 2D, or 3D from a part in the cast). Select a lane&#39;s header for the lane panel: Name, Volume, Mute and Lock.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Right click a sound bar &gt; <strong>Fit scene length to this sound</strong> to make the scene end where the sound does.</li><li>Turn waveforms off in <strong>View &gt; Waveforms</strong>; fades, loops and peak snapping keep working.</li><li>A 2D clip plays flat. A 3D clip plays from its part, though <strong>Settings &gt; Audio &gt; Play sounds in 2D while animating</strong> flattens it in the editor.</li></ul><h2 id="compared-to-roblox-s-animation-editor" tabindex="-1">Compared to Roblox&#39;s Animation Editor <a class="header-anchor" href="#compared-to-roblox-s-animation-editor" aria-label="Permalink to &quot;Compared to Roblox&#39;s Animation Editor&quot;">​</a></h2><p>Roblox&#39;s Animation Editor has animation events, named markers your scripts listen for, but no audio on its timeline. A sound or a particle burst has to be started from your own code at the right moment. In AcesMotion sounds, bursts, Event blocks and your own action modules sit on the same Timeline as the keys, and the runtime plays them in sync in games.</p>',5))])}const k=n(d,[["render",l]]);export{b as __pageData,k as default};
